def amicable_numbers_sum(n):
    """Returns the sum of all amicable numbers pair sums from 1 to n."""
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")

    def digit_sum(x):
        sum_digits = 0
        while x > 0:
            sum_digits += x % 10
            x //= 10
        return sum_digits

    def sum_of_squares(x):
        sum_sq = 0
        while x > 0:
            digit = x % 10
            sum_sq += digit ** 2
            x //= 10
        return sum_sq

    total_sum = 0
    checked_pairs = set()  # To track pairs already summed to avoid duplicates

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (digit_sum(i) == digit_sum(j)) and (i * j == sum_of_squares(i)) and (i * j == sum_of_squares(j)):
                if (i, j) not in checked_pairs:
                    checked_pairs.add((i, j))
                    total_sum += i + j

    return total_sum

