def magic_square(matrix):
    # Step 1: Input Validation
    if not matrix or not all(matrix) or len(matrix) != len(matrix[0]):
        return False
    for row in matrix:
        if not all(isinstance(i, int) for i in row):
            return False
    flattened = [num for row in matrix for num in row]

    # Check for unique elements across the entire matrix
    if len(flattened) != len(set(flattened)):
        return False

    n = len(matrix)
    total_sum = sum(flattened)
    row_sum_expected = total_sum // n

    # Step 2: Verify Row Sums
    for row in matrix:
        if sum(row) != row_sum_expected:
            return False

    # Step 3: Verify Column Sums
    for col in range(n):
        column_sum = sum(matrix[row][col] for row in range(n))
        if column_sum != row_sum_expected:
            return False

    # Step 4: Verify Diagonal Sums
    if sum(matrix[i][i] for i in range(n)) != row_sum_expected:
        return False
    if sum(matrix[i][n-1-i] for i in range(n)) != row_sum_expected:
        return False

    return True
