        raise ValueError("Array is empty.")
    if n != len(sorted_array):
        raise ValueError("Array length does not match provided n.")
    if not all(sorted_array[i] <= sorted_array[i+1] for i in range(len(sorted_array)-1)):
        raise ValueError("Array is not sorted.")
